const moneyText=(n:number|null)=>n===null?'—':(n/100).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});
const localDate=(d:Date)=>new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);
const monthOf=(d:Date)=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;
let month=monthOf(new Date()),page=location.hash.slice(1)||'home',state:State,snap:ReturnType<typeof project>;
let selected=new Set<string>(),query='',typeFilter='',accountFilter='',statusFilter='',drafts:Draft[]=[],importInfo='',busy=false,sessionToken='',sessionKey='';
const typeNames:Record<string,string>={PURCHASE:'消费',INCOME:'收入',INTERNAL_TRANSFER:'内部转账',EXTERNAL_TRANSFER:'转出',DEPOSIT:'押金',RED_PACKET:'红包',REPAYMENT:'还款',REFUND:'退款',RETURN:'退回',WITHDRAWAL:'提现'};
