function toast(s:string){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function error(e:any){const messages:Record<string,string>={ACTIVE_RETURN_LINKS:'这笔交易有关联退款，请先处理退款记录',RETURN_EXCEEDS_ORIGINAL:'累计退款不能超过原交易金额',SAME_ACCOUNT_TRANSFER:'转入和转出账户不能相同',UNRESOLVED_CONFLICT:'存在同步冲突，请先到设置处理',PRIVATE_SYNC_REPO_REQUIRED:'同步仓库必须是私有仓库',GITHUB_AUTH_REQUIRED:'GitHub 令牌无效或已过期',GITHUB_FORBIDDEN_OR_RATE_LIMITED:'GitHub 权限不足或访问过于频繁',GITHUB_NETWORK_ERROR:'连接 GitHub 失败，本地账单已经保留，可稍后重试',AUTHENTICATION_FAILED:'解密失败，请检查恢复密钥',WRONG_LEDGER_OR_KEY:'账本 ID 或恢复密钥不匹配',ACCOUNT_UNAVAILABLE:'请选择有效账户',INVALID_REPAYMENT_ACCOUNTS:'还款需要从资产账户转入负债账户',ORIGINAL_UNAVAILABLE:'请先选择一笔有效的原交易',RETURN_BEFORE_ORIGINAL:'退款时间不能早于原交易',INVALID_TIMESTAMP:'请检查交易日期和时间',SPONSORED_REFUND_HAS_OWN_ACCOUNT:'亲情卡退款不应进入本人账户',INVALID_MONEY:'请输入有效金额',EXPLICIT_RESOLUTION_REQUIRED:'该字段存在冲突，请先在设置中处理'};toast(messages[e?.message]||e?.message||'操作失败，请重试');}
const entities=(type:string)=>snap.entities.filter(e=>e.type===type);
const accounts=()=>entities('accounts').filter(e=>!e.fields.deleted_at);
const transactions=()=>entities('transactions').filter(e=>!e.fields.deleted_at);
const getT=(id:string)=>entities('transactions').find(t=>t.id===id)!;
const effect=(id:string)=>entities('consumption_effects').find(e=>e.fields.transaction_id===id);
const moves=(id:string)=>entities('balance_movements').filter(e=>e.fields.transaction_id===id&&e.fields.amount!==0);
const category=(id:string)=>String(effect(id)?.fields.category_id||'其他');
const accountName=(id:any)=>accounts().find(a=>a.id===id)?.fields.name||'待补认账户';
const accountLabel=(t:Entity)=>{const ms=moves(t.id);return ms.length?ms.map(m=>accountName(m.fields.account_id)).join(' → '):t.fields.event_type==='PURCHASE'&&t.fields.status==='SUCCESS'?'亲情卡 / 他人代付':'无资金变动';};
function inMonth(t:Entity,m=month){return monthOf(new Date(t.fields.occurred_at as string))===m;}
function period(m=month){const [y,n]=m.split('-').map(Number);return [new Date(y,n-1,1).toISOString(),new Date(y,n,1).toISOString()];}
function total(m=month){if(snap.conflicts.length)return null;return consumptionInPeriod(snap,...period(m) as [string,string]);}
function balance(a:Entity){try{return accountBalance(snap,a.id,new Date().toISOString()).balance;}catch{return null;}}
const activeMonth=()=>transactions().filter(t=>inMonth(t)&&t.fields.status==='SUCCESS');
const opts=(entries:[string,any][],v:any)=>entries.map(([id,label])=>`<option value="${esc(id)}" ${id===v?'selected':''}>${esc(label)}</option>`).join('');
const accountOpts=(v='',none=true)=>`${none?'<option value="">稍后补认账户</option>':''}${opts(accounts().map(a=>[a.id,a.fields.name]),v)}`;
function setPage(p:string){page=p;location.hash=p;selected.clear();render();window.scrollTo(0,0);}
async function refresh(){state=await read();snap=project(state.ops);render();}
function empty(title:string,sub:string,action='',label=''){return `<div class="empty"><div class="empty-orbit">${icon('star')}</div><h3>${title}</h3><p>${sub}</p>${action?`<button class="primary" data-action="${action}">${label}</button>`:''}</div>`;}
function shell(content:string){const nav=[['home','概览','home'],['bills','账单','bill'],['accounts','账户','wallet'],['analysis','分析','chart'],['import','导入与核验','import'],['settings','设置','settings']];const mode=state.settings.mode||'auto';document.documentElement.dataset.mode=mode;document.documentElement.dataset.layout=mode==='auto'?(window.innerWidth<=800?'mobile':'desktop'):mode;
 return `<aside class="sidebar"><a class="brand" href="#home"><span class="brand-symbol">${icon('star')}</span><span>星账<small>STAR LEDGER</small></span></a><div class="ledger-label"><span class="avatar">A</span><div>我的个人账本<small>把生活记清楚</small></div><span class="tiny-dot"></span></div><nav>${nav.map(([p,n,i])=>`<button data-page="${p}" class="nav-item ${page===p?'active':''}">${icon(i)}<span>${n}</span>${page===p?'<span class="nav-point"></span>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="local-status"><span class="tiny-dot"></span> 本地自动保存</div><p>每一笔，都有迹可循。</p><button class="quiet" data-action="sync">${icon('sync')} GitHub 同步</button></div></aside>
 <div class="main-shell"><header class="topbar"><div class="breadcrumb">我的账本 <span>/</span> ${nav.find(n=>n[0]===page)?.[1]||'概览'}</div><a href="#home" class="mobile-brand">${icon('star')} 星账</a><div class="top-actions"><span class="connection ${navigator.onLine?'':'offline'}"><i></i>${navigator.onLine?'本地已保存':'离线可用'}</span><button class="icon-button" data-action="sync" title="同步与备份" aria-label="同步与备份">${icon('sync')}</button><button class="profile" data-page="settings" aria-label="打开设置">A</button></div></header><main>${state.settings.demo?'<div class="banner">你正在查看演示账本，所有示例均为虚构数据。<button data-action="clear-demo">结束演示，建立我的账本</button></div>':''}${snap.conflicts.length?`<div class="banner warning">有 ${snap.conflicts.length} 项同步冲突。合计暂时隐藏，避免使用未确认金额。<button data-page="settings">查看冲突</button></div>`:''}${content}</main><footer class="desktop-footer">星账 · 个人版 <span>数据留在你的设备，生活掌握在自己手中。</span></footer></div>
 <nav class="bottom-nav">${nav.slice(0,4).map(([p,n,i])=>`<button data-page="${p}" class="${page===p?'active':''}">${icon(i)}<span>${n}</span></button>`).join('')}<button data-page="settings" class="${page==='settings'?'active':''}">${icon('settings')}<span>更多</span></button></nav><button class="mobile-fab" data-action="new" aria-label="记一笔">${icon('plus')}</button>`;
}
function title(kicker:string,name:string,subtitle:string,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${name}</h1><p>${subtitle}</p></div><div class="heading-actions">${actions}</div></div>`;}
function monthPicker(){return `<label class="month-picker"><input type="month" id="month" value="${month}" aria-label="统计月份"></label>`;}
function trendChart(){const [y,m]=month.split('-').map(Number),days=new Date(y,m,0).getDate();const data=Array.from({length:days},()=>0);if(!snap.conflicts.length)activeMonth().forEach(t=>{data[new Date(t.fields.occurred_at as string).getDate()-1]+=Number(effect(t.id)?.fields.amount||0);});const peak=Math.max(100,...data.map(Math.abs));
 return `<div class="trend"><div class="chart-scale"><span>¥${moneyText(peak)}</span><span>¥0</span></div><div class="bars">${data.map((v,i)=>`<button class="bar-cell" title="${m}月${i+1}日 · ¥${moneyText(v)}" data-day="${i+1}" aria-label="${i+1}日消费 ${moneyText(v)} 元"><span class="bar ${v<0?'negative':''}" style="height:${Math.max(2,Math.abs(v)/peak*100)}%"></span>${[0,7,14,21,days-1].includes(i)?`<small>${i+1}</small>`:''}</button>`).join('')}</div></div>`;
}
function categoryData(){const map=new Map<string,number>();if(!snap.conflicts.length)activeMonth().forEach(t=>{const e=effect(t.id);if(e)map.set(category(t.id),(map.get(category(t.id))||0)+Number(e.fields.amount));});return [...map].sort((a,b)=>b[1]-a[1]);}
function categoriesChart(){const data=categoryData().filter(([,v])=>v>0),sum=data.reduce((a,[,v])=>a+v,0),colors=['#b9dfb9','#819dcd','#dbc393','#aa96c8','#749e98','#c28f89','#8b949e'];if(!sum)return '<div class="chart-empty">有了消费记录，开销结构就会在这里出现。</div>';
 let start=0;const gradient=data.map(([,v],i)=>{const end=start+v/sum*100;const s=`${colors[i%colors.length]} ${start}% ${end}%`;start=end;return s;}).join(',');return `<div class="distribution"><div class="donut" role="img" aria-label="消费分类占比" style="background:conic-gradient(${gradient})"><div><small>最大开销</small><strong>${esc(data[0][0])}</strong><span>${Math.round(data[0][1]/sum*100)}%</span></div></div><div class="legend">${data.slice(0,5).map(([k,v],i)=>`<div><span><i style="background:${colors[i]}"></i>${esc(k)}</span><b>¥${moneyText(v)}</b></div>`).join('')}</div></div>`;
}
function billRows(list:Entity[],compact=false){if(!list.length)return empty('这里还没有账单','记下一笔，慢慢看见生活的轮廓。','new','记第一笔');return `<div class="bill-table ${compact?'compact':''}"><div class="table-head"><span>交易 / 时间</span><span>分类</span><span>账户</span><span>金额</span><span></span></div>${list.map(t=>{const f=t.fields,cat=category(t.id),e=effect(t.id),v=Number(f.display_amount),income=['INCOME','REFUND','RETURN'].includes(String(f.event_type));return `<div class="bill-row ${selected.has(t.id)?'selected':''}">${!compact?`<input class="row-select" type="checkbox" aria-label="选择 ${esc(f.display_name)}" data-select="${esc(t.id)}" ${selected.has(t.id)?'checked':''}>`:''}<button class="bill-main" data-detail="${esc(t.id)}"><span class="category-icon cat-${['餐饮','购物','交通','生活'].indexOf(cat)}">${catIcon[cat]||'✦'}</span><span><strong>${esc(f.display_name)}</strong><small>${new Date(f.occurred_at as string).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'})}<span class="mobile-cat"> · ${esc(cat)}</span></small></span></button><span class="bill-category"><span class="tag">${esc(cat)}</span></span><span class="bill-account">${esc(accountLabel(t))}</span><button class="bill-amount ${income?'positive':''}" data-detail="${esc(t.id)}"><strong>${income?'+':f.event_type==='INTERNAL_TRANSFER'||f.event_type==='REPAYMENT'?'':'−'}${moneyText(v)}</strong><small>${f.status!=='SUCCESS'?statusNames[f.status as string]:e&&Number(e.fields.amount)!==0?typeNames[f.event_type as string]:'不计消费'}</small></button><button class="row-arrow icon-button" data-detail="${esc(t.id)}" aria-label="查看 ${esc(f.display_name)}">${icon('chevron')}</button></div>`;}).join('')}</div>`;}
function home(){const consumed=total(),budget=state.settings.budget||0,remaining=consumed===null?null:budget-consumed,now=new Date(),isCurrent=month===monthOf(now);const [y,m]=month.split('-').map(Number);const previous=monthOf(new Date(y,m-2,1)),prev=total(previous);const as=accounts();const known=as.map(a=>({a,b:balance(a)}));const assets=known.filter(x=>x.a.fields.type==='ASSET').reduce((s,x)=>s+(x.b||0),0),debt=known.filter(x=>x.a.fields.type==='LIABILITY').reduce((s,x)=>s+(x.b||0),0);const hasUnknown=known.some(x=>x.b===null);const recent=transactions().filter(t=>inMonth(t)).sort((a,b)=>String(b.fields.occurred_at).localeCompare(String(a.fields.occurred_at))).slice(0,5);
 return title('A LITTLE CLARITY, EVERY DAY',isCurrent?'把生活，记得清楚。':`${m} 月的生活记录`,'关注真正的消费，也看清每一笔钱的去向。',`${monthPicker()}<button class="primary" data-action="new">${icon('plus')} 记一笔</button>`)+
 `<section class="overview-grid"><div class="spending-hero"><div class="hero-stars">✧</div><div class="card-label">${m} 月真实消费 <span>退款已冲减</span></div><div class="hero-value"><small>¥</small>${moneyText(consumed)}</div><div class="hero-foot"><span>${prev&&consumed!==null?`${consumed>=prev?'↑':'↓'} 较上月 ${Math.abs((consumed-prev)/prev*100).toFixed(1)}%`:'从每一笔记录，认识自己的生活'}</span><span>${activeMonth().length} 笔记录</span></div></div><div class="stat-card"><div class="card-label">预算剩余<button class="text-button" data-action="budget">调整 ${icon('chevron')}</button></div><div class="stat-value ${remaining!==null&&remaining<0?'negative':''}">¥ ${moneyText(remaining)}</div><div class="progress"><i style="width:${consumed===null||!budget?0:Math.max(0,Math.min(100,consumed/budget*100))}%"></i></div><small>月预算 ¥${moneyText(budget)} ${remaining!==null&&remaining<0?'· 已超出预算':''}</small></div><div class="stat-card"><div class="card-label">已知净资产 ${icon('wallet')}</div><div class="stat-value">¥ ${snap.conflicts.length?'—':moneyText(assets-debt)}</div><div class="asset-mini"><span>资产 ¥${moneyText(assets)}</span><span>欠款 ¥${moneyText(debt)}</span></div><small>${hasUnknown?'部分账户余额未建立，未计入合计':as.length?`${as.length} 个账户 · 余额由资金流水推导`:'添加账户，开始记录资金变化'}</small></div></section>
 <section class="quick-actions"><button data-action="capture"><span>${icon('camera')}</span><div><strong>截图记账</strong><small>上传支付详情，核对后入账</small></div>${icon('arrow')}</button><button data-page="import"><span>${icon('import')}</span><div><strong>导入账单</strong><small>微信 / 支付宝 · 补漏与核验</small></div>${icon('arrow')}</button><button data-action="account"><span>${icon('wallet')}</span><div><strong>管理账户</strong><small>钱包、银行卡与现金</small></div>${icon('arrow')}</button></section>
 ${!as.length&&!transactions().length?`<div class="welcome-note"><div><strong>从一个账户开始。</strong><p>先填写期初余额，再记录之后的流水；不确定的余额可以留空。</p></div><button class="secondary" data-action="account">添加账户</button><button class="text-button" data-action="demo">先看看演示</button></div>`:''}
 <section class="chart-grid"><div class="panel"><div class="panel-heading"><h2>消费轨迹</h2><span>每日实际消费 · 元</span></div>${trendChart()}</div><div class="panel"><div class="panel-heading"><h2>钱花在哪里</h2><button class="text-button" data-page="analysis">查看分析 ${icon('arrow')}</button></div>${categoriesChart()}</div></section><section class="panel recent"><div class="panel-heading"><h2>最近账单 <small>${recent.length?'每一笔，都有迹可循':''}</small></h2><button class="text-button" data-page="bills">全部账单 ${icon('arrow')}</button></div>${billRows(recent,true)}</section>`;
}
function filteredBills(){return transactions().filter(t=>inMonth(t)&&(!query||`${t.fields.display_name} ${t.fields.note} ${category(t.id)}`.toLowerCase().includes(query.toLowerCase()))&&(!typeFilter||t.fields.event_type===typeFilter)&&(!statusFilter||t.fields.status===statusFilter)&&(!accountFilter||moves(t.id).some(m=>m.fields.account_id===accountFilter))).sort((a,b)=>String(b.fields.occurred_at).localeCompare(String(a.fields.occurred_at)));}
function bills(){const list=filteredBills();return title('YOUR EVERYDAY, IN DETAILS','账单','保留原始凭证，让每一次记录都可以回看。',`${monthPicker()}<button class="secondary" data-page="import">${icon('import')} 导入</button><button class="primary" data-action="new">${icon('plus')} 记一笔</button>`)+`<div class="filter-bar"><label class="search">${icon('search')}<input id="search" placeholder="搜索商户、分类或备注" value="${esc(query)}"></label><select id="type-filter" aria-label="交易类型"><option value="">全部类型</option>${opts(Object.entries(typeNames),typeFilter)}</select><select id="account-filter" aria-label="筛选账户"><option value="">全部账户</option>${opts(accounts().map(a=>[a.id,a.fields.name]),accountFilter)}</select><select id="status-filter" aria-label="筛选状态"><option value="">全部状态</option>${opts(Object.entries(statusNames),statusFilter)}</select><button class="quiet" data-action="export-csv">导出 CSV</button></div><div class="list-summary"><span>${list.length} 笔账单 <span class="dim">· ${month}</span></span><div><button class="text-button" data-action="select-all">${selected.size===list.length&&list.length?'取消全选':'全选'}</button><button class="text-button" data-action="trash">回收站</button></div></div>${selected.size?`<div class="selection-bar"><span>已选 ${selected.size} 笔</span><button data-action="batch-category">批量分类</button><button data-action="batch-delete">移到回收站</button><button data-action="deselect">取消选择</button></div>`:''}<section class="panel no-pad">${billRows(list)}</section>`;}
function accountsPage(){return title('A PLACE FOR EVERY YUAN','账户','余额与消费各自计算，内部转账不会重复计入消费。','<button class="primary" data-action="account">'+icon('plus')+' 添加账户</button>')+`<div class="accounts-grid">${accounts().map((a,i)=>`<button class="account-card tone-${i%3}" data-account="${esc(a.id)}"><div class="account-card-top"><span class="account-symbol">${icon('wallet')}</span><span>${a.fields.type==='LIABILITY'?'负债账户':'资产账户'}</span>${icon('chevron')}</div><h2>${esc(a.fields.name)}</h2><p>${a.fields.type==='LIABILITY'?'当前欠款':'当前余额'}</p><strong>¥ ${moneyText(balance(a))}</strong><small>${a.fields.last4?'尾号 '+esc(a.fields.last4)+' · ':''}${balance(a)===null?'尚未设置期初余额':'期初 '+new Date(a.fields.opening_balance_at as string).toLocaleDateString('zh-CN')}</small></button>`).join('')}<button class="account-card add-account" data-action="account">${icon('plus')}<strong>添加一个账户</strong><span>微信、支付宝、银行卡或现金</span></button></div><div class="panel explainer"><h2>数字背后的规则</h2><div class="explain-grid"><div><span>01</span><h3>余额从期初开始</h3><p>只累加期初时刻之后的成功流水。导入更早的历史账单，不会重复改变当前余额。</p></div><div><span>02</span><h3>转账不等于消费</h3><p>本人账户互转只移动资金。对外转账可单独指定其中的消费金额。</p></div><div><span>03</span><h3>亲情卡也是真实消费</h3><p>他人代付计入你的消费，不扣减本人资产；未知付款账户会保留待补认。</p></div></div></div>`;}
function analysis(){const v=total(),data=categoryData(),budget=state.settings.budget||0;const [y,m]=month.split('-').map(Number);const prev=total(monthOf(new Date(y,m-2,1)));const purchaseCount=activeMonth().filter(t=>Number(effect(t.id)?.fields.amount)>0).length;return title('UNDERSTAND YOUR RHYTHM','消费分析','看见开销结构，给下一次选择留一点空间。',`${monthPicker()}<button class="secondary" data-action="budget">设置月预算</button>`)+`<section class="analysis-stats"><div><small>本月净消费</small><strong>¥ ${moneyText(v)}</strong></div><div><small>每笔平均消费</small><strong>¥ ${moneyText(v===null?null:purchaseCount?Math.round(v/purchaseCount):0)}</strong></div><div><small>较上月变化</small><strong>${prev&&v!==null?`${v>=prev?'+':''}${((v-prev)/prev*100).toFixed(1)}%`:'—'}</strong></div><div><small>预算使用</small><strong>${v!==null&&budget?(v/budget*100).toFixed(0)+'%':'—'}</strong></div></section><section class="chart-grid"><div class="panel"><div class="panel-heading"><h2>每日消费</h2><span>退款计入发生日</span></div>${trendChart()}</div><div class="panel"><div class="panel-heading"><h2>消费构成</h2></div>${categoriesChart()}</div></section><section class="panel"><div class="panel-heading"><h2>分类明细</h2><span>按消费影响统计</span></div>${data.length?data.map(([k,n])=>`<div class="category-breakdown"><span class="category-icon">${catIcon[k]||'✦'}</span><strong>${esc(k)}</strong><div class="progress"><i style="width:${Math.max(0,n/(Math.max(...data.map(x=>x[1]),1))*100)}%"></i></div><b>¥ ${moneyText(n)}</b></div>`).join(''):empty('还没有可分析的消费','完成记账后，分类明细会自动更新。')}<p class="footnote">收入、内部转账、还款不计消费。退款在退款发生月冲减；负值分类表示本月退回超过新增消费。</p></section>`;}
function importPage(){return title('LESS TYPING, MORE LIVING','导入与核验','截图补上当下，官方账单补齐遗漏。每一条原始记录都会保留。')+`<section class="import-choices"><button class="import-tile" data-action="capture"><span>${icon('camera')}</span><h2>从截图记一笔</h2><p>选择微信 / 支付宝支付详情截图<br>本地识别，核对后保存</p><b>选择截图 ${icon('arrow')}</b></button><button class="import-tile" data-action="import-file"><span>${icon('import')}</span><h2>导入官方账单</h2><p>支持 XLSX、CSV<br>预览、匹配账户、批量确认</p><b>选择账单文件 ${icon('arrow')}</b></button></section><p class="footnote">截图不会上传到识别服务器。首次识别需下载文字识别资源；网页版目前通过选择图片输入。</p>${drafts.length?`<section class="panel"><div class="panel-heading"><div><h2>待核验账单 <small>${drafts.length} 笔</small></h2><p class="dim">${esc(importInfo)}</p></div><button class="quiet" data-action="clear-import">清空本次预览</button></div><div class="import-toolbar"><label>批量付款 / 收款账户<select id="import-account">${accountOpts()}</select></label><button class="secondary" data-action="apply-import-account">应用到待导入记录</button><button class="text-button" data-action="select-safe">选择可直接导入项</button><button class="primary" data-action="commit-import">导入选中 (${drafts.filter(d=>d.selected).length})</button></div><div class="import-list">${drafts.map((d,i)=>{const exists=duplicate(d);return `<div class="import-row"><input type="checkbox" data-draft-select="${i}" aria-label="选择导入 ${esc(d.name)}" ${d.selected?'checked':''} ${exists?'disabled':''}><div><strong>${esc(d.name)} <span class="tag">${typeNames[d.kind]}</span></strong><small>${esc(d.date.replace('T',' '))} · ${esc(d.channel||d.platform)}${d.account?' · '+esc(accountName(d.account)):''}</small><p class="${exists?'positive':d.issue?'negative':'dim'}">${exists?'已存在：重复记录将跳过':esc(d.issue||'可导入；请确认账户')}</p></div><b>¥ ${esc(d.amount)}</b><button class="secondary" data-draft="${i}">核对</button></div>`;}).join('')}</div></section>`:`<div class="panel"><h2>一次核对，避免重复</h2><ol class="steps"><li><b>读取原始账单</b><span>按表头识别交易时间、金额、付款渠道和状态。</span></li><li><b>补充必要的信息</b><span>同一付款渠道可批量匹配账户；退款要关联原交易。</span></li><li><b>确认后统一入账</b><span>相同来源重复导入会跳过；退款、转账等不确定项单独核对。</span></li></ol></div>`}`;}
function settingsPage(){const deleted=entities('transactions').filter(t=>t.fields.deleted_at).length;return title('YOUR DATA, YOUR CHOICE','设置与同步','本地保存是默认，跨设备同步由你开启。')+`<div class="settings-grid"><section class="panel"><h2>显示与偏好</h2><label>页面模式<select id="display-mode">${opts([['auto','自动适配设备'],['desktop','电脑模式'],['mobile','手机模式']],state.settings.mode)}</select></label><p class="footnote">电脑使用侧边导航和管理表格；手机使用底部导航、单列卡片和快捷输入。</p><label>月消费预算<div class="input-action"><input id="budget-input" type="number" min="0.01" step="0.01" value="${(state.settings.budget||0)/100}"><button class="secondary" data-action="save-budget">保存</button></div></label><label>分类管理<div class="category-chips">${state.settings.categories.map((c:string)=>`<span class="tag">${esc(c)}</span>`).join('')}</div><div class="input-action"><input id="category-name" placeholder="添加分类名称" maxlength="30"><button class="secondary" data-action="add-category">添加</button></div></label><p class="footnote">预算与显示偏好保存在本机；账单的分类和备注随账务记录同步。备注中可使用 #标签 进行搜索。</p></section><section class="panel"><div class="panel-heading"><h2>GitHub 加密同步</h2><span class="tag">可选</span></div><p>将加密记录存入独立的私有仓库。在另一台设备填写相同的账本 ID 和恢复密钥，即可恢复记录。</p><div class="sync-overview"><span>${icon('sync')}</span><div><strong>${state.settings.lastSync?'上次同步 '+new Date(state.settings.lastSync).toLocaleString('zh-CN'):'尚未连接同步'}</strong><small>${state.pending.length} 条本地操作待同步</small></div></div><button class="primary full" data-action="sync">配置 / 开始同步</button><p class="footnote">网站仓库只放程序。令牌和恢复密钥只在本次页面会话中使用，不写入网站代码或浏览器持久存储。</p></section><section class="panel"><h2>备份与恢复</h2><p>导出完整账务记录，保存到你自己的设备。恢复采用合并方式，保留现有记录。</p><div class="button-row"><button class="secondary" data-action="backup">导出 JSON 备份</button><button class="secondary" data-action="restore">导入备份</button></div><p class="footnote">备份文件包含明文账单，请自行保管。浏览器清理网站数据会删除本机账本，建议定期备份。</p><button class="text-button" data-action="persist">申请持久存储</button><button class="text-button" data-action="trash">回收站 (${deleted})</button></section><section class="panel"><h2>关于这个版本</h2><p>星账 · 网页个人版 0.7</p><p>电脑和手机访问同一个地址。账单保存在当前浏览器，完成同步配置后才能跨设备共享。</p><div class="button-row"><button class="secondary mobile-only" data-page="import">截图 / 账单导入</button><button class="secondary" data-action="help">使用说明</button>${!state.ops.length?'<button class="text-button" data-action="demo">体验演示账本</button>':''}</div><p class="footnote">全部金额以人民币分计算；未知余额显示为「—」。亲情卡、退款和内部转账使用独立的消费与余额规则。</p></section></div>${snap.conflicts.length?`<section class="panel"><h2>待解决的同步冲突</h2><p>保留双方修改，明确选择后才恢复统计。</p>${snap.conflicts.map((c,i)=>`<div class="conflict"><b>${esc(c.entity_type)} · ${esc(c.field)}</b><small>${esc(c.entity_id)}</small>${['note','category_id','display_name','name'].includes(c.field)?c.candidates.map((v,j)=>`<button class="secondary" data-resolve="${i}:${j}">采用：${esc(v.value)}</button>`).join(''):'<p>此项涉及整笔账务关联，本版暂不提供自动选择。请先导出备份并保留双方记录。</p>'}</div>`).join('')}</section>`:''}`;}
function render(){const pages:Record<string,()=>string>={home,bills,accounts:accountsPage,analysis,import:importPage,settings:settingsPage};if(!pages[page])page='home';app.innerHTML=shell(pages[page]());}
function modal(title:string,content:string,wide=false){dialog.className=wide?'wide':'';dialog.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="icon-button" data-close aria-label="关闭">${icon('close')}</button></div><div class="modal-body">${content}</div>`;if(!dialog.open)dialog.showModal();}
function close(){dialog.close();dialog.innerHTML='';}
function formData(form:HTMLFormElement){return Object.fromEntries(new FormData(form).entries()) as Record<string,string>;}
async function submit(form:HTMLFormElement,fn:()=>Promise<void>){const btn=form.querySelector<HTMLButtonElement>('button[type=submit]');if(btn?.disabled)return;if(btn)btn.disabled=true;try{await fn();}catch(e){error(e);}finally{if(btn)btn.disabled=false;}}
function newRecord(d?:Draft,index?:number,pending?:Entity){const x=d??{kind:'PURCHASE',name:'',amount:'',date:localDate(new Date()),status:'SUCCESS',account:accounts()[0]?.id||'',to:'',category:'餐饮',note:'',original:'',sponsor:false,consumption:'0'};let kind=x.kind;
 const body=()=>`<form id="record-form"><div class="form-grid"><label>交易类型<select name="kind" id="record-kind" ${pending?'disabled':''}>${opts(Object.entries(typeNames),kind)}</select></label><label>交易状态<select name="status" ${pending?'disabled':''}>${opts(Object.entries(statusNames),pending?'SUCCESS':x.status)}</select></label><label class="span2 amount-input">金额 · 元<input name="amount" inputmode="decimal" value="${esc(x.amount)}" placeholder="0.00" required ${pending?'readonly':''}></label><label class="span2">${kind==='PURCHASE'?'商户 / 用途':'交易名称'}<input name="name" maxlength="100" value="${esc(x.name)}" placeholder="例如：午餐、生活用品" required></label><label class="span2">交易时间<input name="date" type="datetime-local" step="1" value="${esc(x.date)}" required ${pending?'readonly':''}></label>${['REFUND','RETURN'].includes(kind)?`<label class="span2">关联原交易<select name="original" required><option value="">选择原消费 / 转出记录</option>${opts(transactions().filter(t=>t.fields.status==='SUCCESS'&&(kind==='REFUND'?t.fields.event_type==='PURCHASE':['EXTERNAL_TRANSFER','DEPOSIT','RED_PACKET'].includes(String(t.fields.event_type)))).map(t=>[t.id,`${t.fields.display_name} · ¥${moneyText(Number(t.fields.display_amount))} · ${String(t.fields.occurred_at).slice(0,10)}`]),x.original)}</select></label>`:''}<label class="${['INTERNAL_TRANSFER','REPAYMENT','WITHDRAWAL'].includes(kind)?'':'span2'}">${['INCOME','REFUND','RETURN'].includes(kind)?'到账账户':'付款 / 转出账户'}<select name="account">${accountOpts(x.account)}</select></label>${['INTERNAL_TRANSFER','REPAYMENT','WITHDRAWAL'].includes(kind)?`<label>转入账户<select name="to">${accountOpts(x.to)}</select></label>`:''}${kind==='PURCHASE'?`<label class="check-label span2"><input name="sponsor" type="checkbox" ${x.sponsor?'checked':''}> 亲情卡 / 他人代付（不扣本人余额）</label>`:''}${['PURCHASE','EXTERNAL_TRANSFER','DEPOSIT','RED_PACKET'].includes(kind)?`<label>消费分类<select name="category">${opts(state.settings.categories.map((c:string)=>[c,c]),x.category)}</select></label>`:''}${['EXTERNAL_TRANSFER','DEPOSIT','RED_PACKET','RETURN'].includes(kind)?`<label>${kind==='RETURN'?'冲减消费金额':'其中计入消费 · 元'}<input name="consumption" inputmode="decimal" value="${esc(x.consumption||'0')}"></label>`:''}${kind==='WITHDRAWAL'?'<label>手续费 · 元<input name="fee" value="0" inputmode="decimal"></label>':''}<label class="span2">备注 / #标签<textarea name="note" rows="2" maxlength="1000" placeholder="留一点关于这笔钱的记忆">${esc(x.note)}</textarea></label></div>${d?.key&&matchCandidates(d).length?`<div class="match-box"><strong>发现可能是同一笔的记录</strong><p>核对后可只补充来源，不再新增消费。</p><select id="match-existing">${opts(matchCandidates(d).map(t=>[t.id,`${t.fields.display_name} · ¥${moneyText(Number(t.fields.display_amount))} · ${new Date(String(t.fields.occurred_at)).toLocaleString('zh-CN')}`]),'')}</select><button type="button" class="secondary" id="attach-source">关联这笔，补充凭证</button></div>`:''}${d?`<details class="source-details"><summary>原始识别 / 账单凭证</summary><pre>${esc(d.raw)}</pre></details><p class="footnote">请核对金额、时间、状态与付款账户。识别结果不会未经确认直接入账。</p>`:'<p class="footnote">待完成 / 未成功的交易暂不影响余额和消费。付款账户留空时保留待补认资金变动。</p>'}<div class="modal-actions"><button type="button" class="secondary" data-close>取消</button><button type="submit" class="primary">${index!==undefined?'确认这是一笔独立记录':pending?'确认交易成功':'保存账单'}</button></div></form>`;
 const draw=()=>{modal(d?'核对并记账':pending?'完成待支付交易':'记一笔',body());if(d&&$('#attach-source'))$('#attach-source').onclick=async()=>{try{await attachSource(d,$<HTMLSelectElement>('#match-existing').value);}catch(e){error(e);}};$('#record-kind')?.addEventListener('change',e=>{const values=formData($('#record-form'));Object.assign(x,values,{sponsor:values.sponsor==='on'});kind=(e.target as HTMLSelectElement).value;draw();});$('#record-form').addEventListener('submit',e=>{e.preventDefault();const form=e.target as HTMLFormElement;submit(form,async()=>{const v=formData(form);v.kind=pending?String(pending.fields.event_type):kind;v.status=pending?'SUCCESS':v.status;const draft={...d,...v,sponsor:v.sponsor==='on'} as any;const cmd=commandFrom(draft);if(index!==undefined){Object.assign(drafts[index],draft,{issue:'',selected:true});close();render();toast('已核对，可批量导入');return;}if(d&&duplicate(d))throw Error('这条记录已经存在，请到导入页查看，避免重复记账');if(pending){cmd.id=pending.id;cmd.occurredAt=String(pending.fields.occurred_at);await business({kind:'SET_STATUS',transactionId:pending.id,status:'SUCCESS',settlement:cmd});}else await business(cmd);close();await refresh();toast('已保存到账本');});});};draw();}
function commandFrom(v:any):FinancialEvent{const amount=money(String(v.amount));const date=new Date(v.date);if(!Number.isFinite(date.getTime()))throw Error('请填写有效的交易时间');const base={id:v.key?'import-'+v.key:crypto.randomUUID(),occurredAt:date.toISOString(),name:v.name.trim(),amount,status:v.status as any,note:v.note||'',...(v.key?{source:{id:'source-'+v.key,sourceType:v.sourceType,platform:v.platform,rawPayload:JSON.stringify({key:v.key,order:v.order,channel:v.channel,original:v.raw})}}:{})};const a=v.account||null;const zero=(s:any)=>s===''||s===undefined||Number(s)===0?0:money(String(s));switch(v.kind){case 'PURCHASE':return {...base,kind:v.kind,payer:v.sponsor?null:a,categoryId:v.category,funding:v.sponsor?'EXTERNAL_SPONSOR':'OWN'};case 'INCOME':return {...base,kind:v.kind,destination:a};case 'INTERNAL_TRANSFER':return {...base,kind:v.kind,from:a,to:v.to||null};case 'WITHDRAWAL':return {...base,kind:v.kind,from:a,to:v.to||null,fee:zero(v.fee)};case 'REPAYMENT':return {...base,kind:v.kind,from:a!,to:v.to};case 'REFUND':return {...base,kind:v.kind,originalId:v.original,destination:a};case 'RETURN':return {...base,kind:v.kind,originalId:v.original,destination:a,consumptionReduction:zero(v.consumption)};case 'EXTERNAL_TRANSFER':case 'DEPOSIT':case 'RED_PACKET':return {...base,kind:v.kind,from:a,consumptionAmount:zero(v.consumption),categoryId:v.category};default:throw Error('未知交易类型');}}
function accountDialog(id?:string){const a=id?accounts().find(a=>a.id===id):undefined;modal(a?'账户详情':'添加账户',`<form id="account-form"><div class="form-grid"><label class="span2">账户名称<input name="name" placeholder="例如：招商银行卡、微信余额" value="${esc(a?.fields.name||'')}" maxlength="60" required></label><label>账户类型<select name="type" ${a?'disabled':''}>${opts([['ASSET','资产 · 钱包 / 银行卡 / 现金'],['LIABILITY','负债 · 信用账户']],a?.fields.type||'ASSET')}</select></label><label>尾号（可选）<input name="last4" pattern="[0-9]{0,4}" maxlength="4" value="${esc(a?.fields.last4||'')}"></label><label>期初余额 / 欠款 · 元<input name="balance" inputmode="decimal" placeholder="不确定可以留空" value="${a?.fields.balance_state==='ESTABLISHED'?Number(a.fields.opening_balance)/100:''}"></label><label>期初时刻<input name="date" type="datetime-local" step="1" value="${a?localDate(new Date(a.fields.opening_balance_at as string)):localDate(new Date())}" required></label></div><p class="footnote">填写这个时刻的余额，系统只累加此后发生的流水。导入历史账单时，请特别注意期初时刻。留空表示余额未知。</p>${a?`<div class="balance-line">当前${a.fields.type==='LIABILITY'?'欠款':'余额'}<strong>¥ ${moneyText(balance(a))}</strong></div>`:''}<div class="modal-actions"><button type="button" class="secondary" data-close>取消</button><button type="submit" class="primary">保存账户</button></div></form>`);$('#account-form').addEventListener('submit',e=>{e.preventDefault();const form=e.target as HTMLFormElement;submit(form,async()=>{const v=formData(form);const n=v.balance.trim()===''?null:Number(v.balance)===0?0:money(v.balance),at=new Date(v.date).toISOString();if(a){const fields={name:v.name,last4:v.last4,opening_balance:n??0,opening_balance_at:at,balance_state:n===null?'UNINITIALIZED':'ESTABLISHED'};await raw(Object.entries(fields).map(([k,value])=>({action:'PATCH_FIELD',entity:{type:'accounts',id:a.id,fields:{[k]:value}}})));}else await business({kind:'CREATE_ACCOUNT',id:crypto.randomUUID(),name:v.name,accountType:v.type as any,openingBalance:n,openingBalanceAt:at,last4:v.last4});close();await refresh();toast('账户已保存');});});}
function detail(id:string){const t=getT(id);if(!t)return;const f=t.fields,effectRow=effect(id),sources=entities('source_records').filter(s=>s.fields.transaction_id===id);const list=filteredBills(),at=list.findIndex(x=>x.id===id);modal('账单详情',`<div class="detail-hero"><span class="category-icon">${catIcon[category(id)]||'✦'}</span><h3>${esc(f.display_name)}</h3><strong>¥ ${moneyText(Number(f.display_amount))}</strong><span class="tag">${typeNames[String(f.event_type)]} · ${statusNames[String(f.status)]}</span></div><div class="detail-facts"><span>发生时间</span><b>${new Date(String(f.occurred_at)).toLocaleString('zh-CN')}</b><span>资金账户</span><b>${esc(accountLabel(t))}</b><span>对消费的影响</span><b>¥ ${moneyText(Number(effectRow?.fields.amount||0))}</b></div><form id="detail-form"><label>名称<input name="name" value="${esc(f.display_name)}" maxlength="100" required></label>${effectRow?`<label>分类<select name="category">${opts([...new Set([...state.settings.categories,category(id)])].map(c=>[String(c),c]),category(id))}</select></label>`:''}<label>备注 / #标签<textarea name="note" rows="3" maxlength="1000">${esc(f.note)}</textarea></label><div class="button-row">${moves(id).filter(m=>m.fields.account_id===null).map(m=>`<button type="button" class="secondary" data-bind="${esc(m.id)}">补认${Number(m.fields.amount)<0?'付款':'收款'}账户</button>`).join('')}${f.status==='SUCCESS'&&['EXTERNAL_TRANSFER','DEPOSIT','RED_PACKET'].includes(String(f.event_type))?`<button type="button" class="secondary" data-meaning="${esc(id)}">调整消费用途</button>`:''}${f.status==='SUCCESS'&&['PURCHASE','EXTERNAL_TRANSFER','DEPOSIT','RED_PACKET'].includes(String(f.event_type))?`<button type="button" class="secondary" data-refund="${esc(id)}">记录退款 / 退回</button>`:''}${f.status==='PENDING'?`<button type="button" class="secondary" data-settle="${esc(id)}">确认成功</button><button type="button" class="secondary" data-fail="${esc(id)}">标记失败</button>`:''}</div>${sources.length?`<details class="source-details"><summary>查看不可修改的原始凭证 (${sources.length})</summary>${sources.map(s=>`<p>${esc(s.fields.platform)} · ${esc(s.fields.source_type)}</p><pre>${esc(s.fields.raw_payload)}</pre>`).join('')}</details>`:'<p class="footnote">手动记录。金额、账户和类型录错时，可移至回收站后重新记录；原始导入凭证不会被备注修改覆盖。</p>'}<div class="modal-actions"><button type="button" class="danger quiet" data-delete="${esc(id)}">移至回收站</button><div>${at>0?`<button type="button" class="quiet" data-detail="${esc(list[at-1].id)}">上一笔</button>`:''}${at>=0&&at<list.length-1?`<button type="button" class="quiet" data-detail="${esc(list[at+1].id)}">下一笔</button>`:''}<button type="submit" class="primary">保存修改</button></div></div></form>`);$('#detail-form').addEventListener('submit',ev=>{ev.preventDefault();const form=ev.target as HTMLFormElement;submit(form,async()=>{const v=formData(form);const commands:Command[]=[{action:'PATCH_FIELD',entity:{type:'transactions',id,fields:{display_name:v.name}}},{action:'PATCH_FIELD',entity:{type:'transactions',id,fields:{note:v.note}}}];if(effectRow)commands.push({action:'PATCH_FIELD',entity:{type:'consumption_effects',id:effectRow.id,fields:{category_id:v.category}}});await raw(commands);close();await refresh();toast('修改已保存');});});}
function confirmAction(title:string,message:string,fn:()=>Promise<void>,label='确认'){modal(title,`<p>${message}</p><form id="confirm-form"><div class="modal-actions"><button type="button" class="secondary" data-close>取消</button><button class="primary" type="submit">${label}</button></div></form>`);$('#confirm-form').addEventListener('submit',e=>{e.preventDefault();submit(e.target as HTMLFormElement,async()=>{await fn();close();await refresh();});});}
function refund(id:string){const t=getT(id);const originalMoves=moves(id);const refundKind=t.fields.event_type==='PURCHASE'?'REFUND':'RETURN';newRecord({key:'',platform:'手动',name:'退回 · '+t.fields.display_name,amount:'',date:localDate(new Date()),kind:refundKind,status:'SUCCESS',channel:'',account:String(originalMoves[0]?.fields.account_id||''),to:'',category:category(id),original:id,note:'',raw:'',issue:'',selected:false,sourceType:'EXCEL',order:'',sponsor:false,consumption:'0'});}
function duplicate(d:Draft){const source=entities('source_records').find(s=>s.id==='source-'+d.key);return source?getT(String(source.fields.transaction_id)):entities('transactions').find(t=>t.id==='import-'+d.key);}
function matchCandidates(d:Draft){if(!d.amount||!d.date)return [];let amount:number;try{amount=money(d.amount);}catch{return [];}const date=new Date(d.date).getTime();if(!Number.isFinite(date))return [];return transactions().filter(t=>Number(t.fields.display_amount)===amount&&t.fields.event_type===d.kind&&Math.abs(new Date(String(t.fields.occurred_at)).getTime()-date)<24*60*60*1000&&t.fields.status===d.status);}
async function attachSource(d:Draft,id:string){if(duplicate(d))throw Error('这条来源已经存在');if(!matchCandidates(d).some(t=>t.id===id))throw Error('请选择金额、类型和状态一致的候选交易');await raw([{action:'CREATE_ENTITY',entity:{type:'source_records',id:'source-'+d.key,fields:{transaction_id:id,source_type:d.sourceType,platform:d.platform,raw_payload:JSON.stringify({key:d.key,order:d.order,channel:d.channel,original:d.raw}),created_at:new Date(d.date).toISOString()}}}]);await refresh();close();toast('已关联到原交易，没有重复记账');}

async function importFile(){const file=await chooseFile('.xlsx,.csv');if(!file)return;if(file.size>15*1024*1024)throw Error('账单文件不能超过 15 MB');toast('正在读取账单…');let rows:any[][];if(file.name.toLowerCase().endsWith('.csv')){const bytes=await file.arrayBuffer();let text=new TextDecoder('utf-8').decode(bytes);if(text.includes('\uFFFD'))text=new TextDecoder('gb18030').decode(bytes);rows=csv(text);}else{const {default:readXlsxFile}=await import('read-excel-file');rows=await readXlsxFile(file);}drafts=parseRows(rows);for(const d of drafts){if(duplicate(d))d.selected=false;const matches=accounts().filter(a=>String(a.fields.name)===d.channel||(a.fields.last4&&d.channel.includes(String(a.fields.last4))));if(matches.length===1)d.account=matches[0].id;if(!duplicate(d)&&matchCandidates(d).length){d.issue='有金额、日期相近的同类记录，请核对是否同一笔';d.selected=false;}}
 importInfo=`${file.name} · ${drafts.filter(d=>duplicate(d)).length} 笔已存在 · 未入账前可修改预览`;setPage('import');}
function chooseFile(accept:string):Promise<File|undefined>{return new Promise(resolve=>{const input=document.createElement('input');input.type='file';input.accept=accept;input.onchange=()=>resolve(input.files?.[0]);input.addEventListener('cancel',()=>resolve(undefined));input.click();});}
function download(name:string,text:string,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
async function capture(){const file=await chooseFile('image/png,image/jpeg,image/webp');if(!file)return;if(file.size>12*1024*1024)throw Error('截图不能超过 12 MB');const fingerprint=hash(Array.from(new Uint8Array(await file.arrayBuffer())));const preview=URL.createObjectURL(file);let worker:any;let cancelled=false;modal('截图识别',`<div class="capture-preview"><img src="${preview}" alt="待识别支付截图"><div><h3>图片留在你的设备</h3><p id="ocr-progress">准备文字识别资源…</p><p class="footnote">首次使用需要联网下载简体中文和英文识别资源，后续核对金额、日期与付款账户。</p><button class="secondary" id="cancel-ocr">停止识别</button></div></div>`);const stop=()=>{cancelled=true;worker?.terminate();URL.revokeObjectURL(preview);};dialog.addEventListener('close',stop,{once:true});$('#cancel-ocr').onclick=()=>close();try{const {createWorker}=await import('tesseract.js');worker=await createWorker(['chi_sim','eng'],1,{workerPath:'https://cdn.jsdelivr.net/npm/tesseract.js@6.0.1/dist/worker.min.js',corePath:'https://cdn.jsdelivr.net/npm/tesseract.js-core@6.1.2',langPath:'https://tessdata.projectnaptha.com/4.0.0',logger:m=>{if(!cancelled&&$('#ocr-progress'))$('#ocr-progress').textContent=m.status==='recognizing text'?`正在识别文字… ${Math.round(m.progress*100)}%`:'正在加载识别资源…';}});if(cancelled){await worker.terminate();return;}const result=await worker.recognize(file);await worker.terminate();worker=undefined;if(cancelled)return;dialog.removeEventListener('close',stop);URL.revokeObjectURL(preview);const d=parseScreenshot(result.data.text,fingerprint);newRecord(d);}catch(e){if(!cancelled){dialog.removeEventListener('close',stop);worker?.terminate();URL.revokeObjectURL(preview);modal('暂时无法识别',`<p>文字识别资源加载或识别失败。你可以稍后重试，也可以手动记下这笔交易。</p><p class="footnote">图片未上传到账本外的服务器。</p><button class="primary" data-action="new">手动记一笔</button>`);}}}
async function commitImport(){const rows=drafts.filter(d=>d.selected&&!duplicate(d));if(!rows.length)throw Error('请先选择要导入的记录');if(rows.some(d=>d.issue))throw Error('所选记录仍有待核验项，请点击「核对」');await mutate(store=>{const service=new BusinessAccountingService(store,store.state.device);for(const d of rows){if(store.get('transactions','import-'+d.key))continue;service.execute(commandFrom(d));}});await refresh();for(const d of rows)d.selected=false;render();toast(`已导入 ${rows.length} 笔，原始凭证已保留`);}
function syncDialog(){const config=state.settings.syncConfig||{owner:'AsteriaAnna',repo:'ledger-sync-test',branch:'main',ledger:'personal-web'};modal('跨设备加密同步',`<form id="sync-form"><p>使用私有数据仓库。另一台设备需要相同的仓库、账本 ID 和恢复密钥。</p><div class="form-grid"><label>GitHub 用户名<input name="owner" value="${esc(config.owner)}" required></label><label>私有数据仓库<input name="repo" value="${esc(config.repo)}" required></label><label>分支<input name="branch" value="${esc(config.branch)}" required></label><label>账本 ID<input name="ledger" value="${esc(config.ledger)}" pattern="[A-Za-z0-9_-]{1,100}" required></label><label class="span2">访问令牌 · 本次会话有效<input name="token" type="password" autocomplete="off" placeholder="仅需该私有仓库 Contents 读写权限" value="${esc(sessionToken)}" required></label><label class="span2">恢复密钥 · 两端必须相同<input id="recovery-key" name="key" type="password" autocomplete="off" value="${esc(sessionKey)}" pattern="[A-Za-z0-9_-]{43}" required><span class="button-row"><button type="button" class="text-button" id="new-key">生成新账本密钥</button><button type="button" class="text-button" id="read-key">读取已有密钥文件</button></span></label></div><p class="footnote">生成密钥会下载恢复文件。请保管好它，已有账本应读取原密钥。网站不会替你找回丢失的密钥。</p><p id="sync-progress" role="status"></p><div class="modal-actions"><button type="button" class="secondary" data-close>稍后</button><button type="submit" class="primary">加密并同步</button></div></form>`);$('#new-key').onclick=()=>{if(state.settings.syncTarget){toast('已连接的账本需要使用原恢复密钥');return;}const bytes=crypto.getRandomValues(new Uint8Array(32));sessionKey=btoa(String.fromCharCode(...bytes)).replace(/\+/g,'-').replace(/\//g,'_').replace(/=/g,'');$<HTMLInputElement>('#recovery-key').value=sessionKey;download('star-ledger-recovery.key',sessionKey,'text/plain');toast('恢复密钥已下载，请在另一台设备使用相同文件');};$('#read-key').onclick=async()=>{const f=await chooseFile('.key,.txt');if(!f)return;const key=(await f.text()).trim();if(!/^[A-Za-z0-9_-]{43}$/.test(key)){toast('密钥文件格式不正确');return;}sessionKey=key;$<HTMLInputElement>('#recovery-key').value=key;};$('#sync-form').addEventListener('submit',e=>{e.preventDefault();submit(e.target as HTMLFormElement,async()=>{if(state.settings.demo)throw Error('演示账本不能同步，请先结束演示');const v=formData(e.target as HTMLFormElement);sessionToken=v.token;sessionKey=v.key;await synchronize(v as any,s=>{if($('#sync-progress'))$('#sync-progress').textContent=s;});await refresh();close();toast('同步完成，已核验远端记录');});});}
function trash(){const ts=entities('transactions').filter(t=>t.fields.deleted_at);modal('回收站',ts.length?`<p class="footnote">移除的交易不参与统计，原始证据仍保留。重新导入相同来源会识别为已有记录，可在这里恢复。</p>${ts.map(t=>`<div class="trash-row"><div><strong>${esc(t.fields.display_name)}</strong><small>¥ ${moneyText(Number(t.fields.display_amount))}</small></div><button class="secondary" data-restore="${esc(t.id)}">恢复</button></div>`).join('')}`:'<p>回收站是空的。</p>');}
async function restoreTransaction(id:string){await mutate(store=>{new AccountingService(store,store.state.device).execute([{action:'RESOLVE_CONFLICT',entity:{type:'transactions',id,fields:{deleted_at:null}}}]);if(project(store.state.ops).conflicts.length)throw Error('恢复会与现有账务冲突，请先处理关联记录');});await refresh();trash();toast('账单已恢复');}
function budgetDialog(){modal('月消费预算',`<form id="budget-form"><label>每月预算 · 元<input name="budget" type="number" min="0.01" step="0.01" value="${state.settings.budget/100}" required></label><p class="footnote">按真实消费扣减，退款冲减发生月消费。预算设置保存在本机。</p><div class="modal-actions"><button type="submit" class="primary">保存预算</button></div></form>`);$('#budget-form').onsubmit=e=>{e.preventDefault();submit(e.target as HTMLFormElement,async()=>{await settings({budget:money(formData(e.target as HTMLFormElement).budget)});close();await refresh();});};}
function batchCategory(){modal('批量修改分类',`<form id="batch-form"><p>将修改选中的 ${selected.size} 笔账单中已有消费影响的分类。</p><label>分类<select name="category">${opts(state.settings.categories.map((c:string)=>[c,c]),'')}</select></label><div class="modal-actions"><button type="submit" class="primary">保存分类</button></div></form>`);$('#batch-form').onsubmit=ev=>{ev.preventDefault();submit(ev.target as HTMLFormElement,async()=>{const c=formData(ev.target as HTMLFormElement).category;const es=[...selected].map(effect).filter(Boolean) as Entity[];if(!es.length)throw Error('选中的账单没有可修改的消费分类');await raw(es.map(e=>({action:'PATCH_FIELD',entity:{type:'consumption_effects',id:e.id,fields:{category_id:c}}})));selected.clear();close();await refresh();});};}
function bind(id:string){modal('补认资金账户',`<form id="bind-form"><label>账户<select name="account" required>${accountOpts('',false)}</select></label><p class="footnote">只补充资金实际进出的账户，不改变原始凭证与消费金额。</p><div class="modal-actions"><button type="submit" class="primary">确认账户</button></div></form>`);$('#bind-form').onsubmit=e=>{e.preventDefault();submit(e.target as HTMLFormElement,async()=>{await business({kind:'BIND_ACCOUNT',movementId:id,accountId:formData(e.target as HTMLFormElement).account});close();await refresh();});};}
function meaning(id:string){modal('调整转账的消费用途',`<form id="meaning-form"><p>资金已转出。请明确其中有多少属于真实消费，其余资金不自动认定为消费。</p><label>计入消费 · 元<input name="amount" inputmode="decimal" value="${Number(effect(id)?.fields.amount||0)/100}" required></label><label>分类<select name="category">${opts(state.settings.categories.map((c:string)=>[c,c]),category(id))}</select></label><div class="modal-actions"><button type="submit" class="primary">保存用途</button></div></form>`);$('#meaning-form').onsubmit=e=>{e.preventDefault();submit(e.target as HTMLFormElement,async()=>{const v=formData(e.target as HTMLFormElement);await business({kind:'SET_CONSUMPTION',transactionId:id,amount:Number(v.amount)===0?0:money(v.amount),categoryId:v.category});close();await refresh();});};}
async function demo(){if(state.ops.length)throw Error('演示仅能在空账本中开启');await mutate(store=>{const svc=new BusinessAccountingService(store,store.state.device);const [y,m]=month.split('-').map(Number);const opening=new Date(y,m-1,1,0,0,0).toISOString();for(const [id,name,b] of [['demo-bank','日常银行卡',800000],['demo-wechat','微信余额',125000],['demo-alipay','支付宝余额',50000]] as const)svc.execute({kind:'CREATE_ACCOUNT',id,name,accountType:'ASSET',openingBalance:b,openingBalanceAt:opening});const sample=[['巷口咖啡',2800,'餐饮'],['地铁出行',500,'交通'],['周末的鲜花',4500,'生活'],['午餐 · 好好吃饭',3200,'餐饮'],['一本新书',6800,'学习'],['超市采购',12650,'生活'],['朋友小聚',16800,'餐饮'],['日用品补充',8900,'购物'],['电影之夜',4200,'娱乐'],['早餐',1200,'餐饮']];sample.forEach(([name,amount,cat],i)=>svc.execute({kind:'PURCHASE',id:'demo-'+i,name:String(name),amount:Number(amount),occurredAt:new Date(y,m-1,Math.min(i*2+1,new Date(y,m,0).getDate()),12,0).toISOString(),payer:i%2?'demo-bank':'demo-wechat',categoryId:String(cat),note:'虚构示例，用于体验页面'}));store.state.settings.demo=true;store.state.settings.budget=300000;});await refresh();toast('已开启演示账本');}
const actions:Record<string,()=>any>={new:()=>newRecord(),account:()=>accountDialog(),capture, 'import-file':importFile, 'commit-import':commitImport, 'clear-import':()=>{drafts=[];render();}, 'select-safe':()=>{drafts.forEach(d=>d.selected=!d.issue&&!duplicate(d));render();},'apply-import-account':()=>{const id=$<HTMLSelectElement>('#import-account').value;drafts.filter(d=>!duplicate(d)).forEach(d=>{if(!d.sponsor)d.account=id;});render();toast('已应用到待导入记录，退款和转账仍需单独核对');},budget:budgetDialog,sync:syncDialog,trash,demo,'clear-demo':()=>confirmAction('结束演示','演示交易将被清空，然后开始你的个人账本。',async()=>{await mutate(store=>{store.state.ops=[];store.state.pending=[];store.state.batches=[];store.state.envelopes={};store.state.settings.demo=false;});},'开始我的账本'),'select-all':()=>{const list=filteredBills();selected=selected.size===list.length?new Set():new Set(list.map(t=>t.id));render();},deselect:()=>{selected.clear();render();},'batch-category':batchCategory,'batch-delete':()=>confirmAction('移至回收站',`将选中的 ${selected.size} 笔交易移至回收站。有关联退款的原交易需要先处理退款。`,async()=>{await mutate(store=>{const svc=new BusinessAccountingService(store,store.state.device);const sorted=[...selected].sort((a,b)=>Number(['REFUND','RETURN'].includes(String(getT(b).fields.event_type)))-Number(['REFUND','RETURN'].includes(String(getT(a).fields.event_type))));for(const id of sorted)svc.execute({kind:'DELETE_TRANSACTION',transactionId:id,deletedAt:new Date().toISOString()});});selected.clear();},'确认移除'),backup:async()=>download('star-ledger-'+new Date().toISOString().slice(0,10)+'.json',await backup()),restore:async()=>{const file=await chooseFile('.json');if(!file)return;if(file.size>30*1024*1024)throw Error('备份文件过大');const text=await file.text();confirmAction('合并恢复备份','会将备份中的账务记录合并到本机，重复操作会跳过。',async()=>{await restore(text);toast('备份已合并');},'合并恢复');},persist:async()=>toast(await navigator.storage?.persist?.()?'已获准持久存储，仍建议定期备份':'浏览器未授予持久存储，请定期导出备份'),'save-budget':async()=>{await settings({budget:money($<HTMLInputElement>('#budget-input').value)});await refresh();toast('预算已保存');},'add-category':async()=>{const name=$<HTMLInputElement>('#category-name').value.trim();if(!name)return;if(state.settings.categories.includes(name))throw Error('分类已存在');await settings({categories:[...state.settings.categories,name]});await refresh();},'export-csv':()=>{const q=(s:any)=>'"'+String(s??'').replace(/"/g,'""').replace(/^([=+@-])/,'\t$1')+'"';const rows=[['时间','名称','类型','状态','金额元','分类','账户','备注'],...filteredBills().map(t=>[new Date(String(t.fields.occurred_at)).toLocaleString('zh-CN'),t.fields.display_name,typeNames[String(t.fields.event_type)],statusNames[String(t.fields.status)],Number(t.fields.display_amount)/100,category(t.id),accountLabel(t),t.fields.note])];download('star-ledger-'+month+'.csv','\uFEFF'+rows.map(r=>r.map(q).join(',')).join('\r\n'),'text/csv;charset=utf-8');},help:()=>modal('开始使用星账',`<ol class="steps"><li><b>建立账户</b><span>填写期初时刻的余额。不确定时留空，历史流水仍可记录。</span></li><li><b>记下日常消费</b><span>手机从「概览 → 截图记账」选择图片，核对后保存；也能随时手动记一笔。</span></li><li><b>电脑整理账单</b><span>导入微信 / 支付宝 XLSX 或 CSV，批量指定账户，逐项核对退款和用途不明的转账。</span></li><li><b>连接另一台设备</b><span>在设置中填写私有数据仓库和令牌，两端使用相同账本 ID 与恢复密钥。每次点击同步交换修改。</span></li><li><b>定期备份</b><span>导出 JSON 备份。清理浏览器网站数据会删除本机记录。截图识别首次需要网络，网页加载完成后基本记账支持离线。</span></li></ol><p class="footnote">本版不读取旧版网页账本，旧版继续在原链接使用。截图识别需核对；涉及整笔账务的复杂同步冲突会保留记录并暂停合计。</p>`,true)};
document.addEventListener('click',async ev=>{const el=(ev.target as Element).closest<HTMLElement>('button,a[data-page]');if(!el)return;try{if(el.hasAttribute('data-close')){close();return;}const d=el.dataset;if(d.page){close();setPage(d.page);return;}if(d.action){await actions[d.action]?.();return;}if(d.detail){detail(d.detail);return;}if(d.account){accountDialog(d.account);return;}if(d.draft!==undefined){newRecord(drafts[Number(d.draft)],Number(d.draft));return;}if(d.refund){refund(d.refund);return;}if(d.delete){confirmAction('移至回收站','此笔交易将从统计中移除，原始凭证仍保留，可从回收站恢复。',async()=>{await business({kind:'DELETE_TRANSACTION',transactionId:d.delete!,deletedAt:new Date().toISOString()});},'确认移除');return;}if(d.restore){await restoreTransaction(d.restore);return;}if(d.bind){bind(d.bind);return;}if(d.meaning){meaning(d.meaning);return;}if(d.settle){const t=getT(d.settle);newRecord({kind:String(t.fields.event_type),name:String(t.fields.display_name),amount:String(Number(t.fields.display_amount)/100),date:localDate(new Date(String(t.fields.occurred_at))),status:'SUCCESS',account:'',to:'',category:'其他',original:'',note:String(t.fields.note),sponsor:false,consumption:'0'} as Draft,undefined,t);return;}if(d.fail){await business({kind:'SET_STATUS',transactionId:d.fail,status:'FAILED'});close();await refresh();return;}if(d.resolve){const [i,j]=d.resolve.split(':').map(Number),c=snap.conflicts[i];await raw([{action:'RESOLVE_CONFLICT',entity:{type:c.entity_type,id:c.entity_id,fields:{[c.field]:c.candidates[j].value}}}]);await refresh();toast('冲突已解决');return;}if(d.day){const amount=activeMonth().filter(t=>new Date(String(t.fields.occurred_at)).getDate()===Number(d.day)).reduce((sum,t)=>sum+Number(effect(t.id)?.fields.amount||0),0);toast(`${month}-${d.day} · 净消费 ¥${moneyText(snap.conflicts.length?null:amount)}`);}}catch(e){error(e);}});
document.addEventListener('change',async ev=>{const el=ev.target as HTMLInputElement;try{if(el.id==='month'){month=el.value;selected.clear();render();}if(el.id==='type-filter'){typeFilter=el.value;render();}if(el.id==='account-filter'){accountFilter=el.value;render();}if(el.id==='status-filter'){statusFilter=el.value;render();}if(el.dataset.select){el.checked?selected.add(el.dataset.select):selected.delete(el.dataset.select);render();}if(el.dataset.draftSelect!==undefined){drafts[Number(el.dataset.draftSelect)].selected=el.checked;render();}if(el.id==='display-mode'){await settings({mode:el.value});await refresh();}}catch(e){error(e);}});
let searchTimer:ReturnType<typeof setTimeout>;document.addEventListener('input',ev=>{const el=ev.target as HTMLInputElement;if(el.id==='search'){query=el.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{const pos=el.selectionStart;render();const input=$<HTMLInputElement>('#search');input.focus();input.setSelectionRange(pos,pos);},250);}});
window.addEventListener('hashchange',()=>{page=location.hash.slice(1)||'home';render();});window.addEventListener('online',()=>{if(state)render();});window.addEventListener('offline',()=>{if(state)render();});window.addEventListener('focus',()=>{if(state&&!dialog.open)refresh().catch(error);});
(async()=>{try{await openStore();const view=new URLSearchParams(location.search).get('view');if(view==='mobile'||view==='desktop'||view==='auto')await settings({mode:view});await refresh();if('serviceWorker'in navigator&&import.meta.env.PROD)navigator.serviceWorker.register('./sw.js',{scope:'./'}).catch(()=>{});}catch(e){app.innerHTML='<div class="startup-error"><h1>暂时无法打开本地账本</h1><p>请使用支持 IndexedDB 的浏览器，并允许网站存储。隐私模式或存储空间不足可能阻止保存。</p><button onclick="location.reload()">重试</button></div>';error(e);}})();

window.addEventListener('resize',()=>{if(state){const mode=state.settings.mode||'auto';document.documentElement.dataset.layout=mode==='auto'?(window.innerWidth<=800?'mobile':'desktop'):mode;}});
